const PORTAL_HTML='<div class="opg-ptl">\n<style>\n.opg-ptl{margin:14px 0;display:flex;justify-content:center}\n.opg-ptl-btn{position:relative;display:inline-flex;align-items:center;gap:8px;max-width:240px;padding:.8em 1.4em;border-radius:18px;cursor:pointer;overflow:hidden;background:linear-gradient(135deg,rgba(255,235,240,.16),rgba(255,202,215,.16));border:1px solid rgba(255,255,255,.28);box-shadow:0 4px 12px rgba(0,0,0,.35),inset 0 0 0 1px rgba(255,255,255,.22),inset 0 -3px 3px rgba(255,255,255,.12);backdrop-filter:blur(13px);-webkit-backdrop-filter:blur(13px);transition:transform .3s ease,box-shadow .3s ease,background .3s ease}\n.opg-ptl-btn::after{content:"";position:absolute;top:-50%;left:-50%;width:200%;height:200%;background:radial-gradient(circle,rgba(255,255,255,.22) 0%,rgba(255,255,255,0) 65%);opacity:.5;pointer-events:none}\n.opg-ptl-btn:hover{transform:translateY(-2px);box-shadow:0 8px 18px rgba(0,0,0,.45),inset 0 0 0 1px rgba(255,255,255,.32),inset 0 -3px 3px rgba(255,255,255,.18);background:linear-gradient(135deg,rgba(255,235,240,.24),rgba(255,202,215,.24))}\n.opg-ptl-btn:active{transform:translateY(0)}\n.opg-ptl-ic{font-size:16px}\n.opg-ptl-tx{font-size:13px;font-weight:700;letter-spacing:.5px;color:#ffeef4;text-shadow:0 1px 1px rgba(0,0,0,.4)}\n@media (max-width:430px){.opg-ptl-btn{padding:.7em 1.1em}.opg-ptl-tx{font-size:12px}}\n@media (prefers-reduced-motion:reduce){.opg-ptl-btn{transition:none}}\n</style>\n<div class="opg-ptl-btn"><span class="opg-ptl-ic">📖</span><span class="opg-ptl-tx">翻开 {{char}} 的日记</span></div>\n</div>';
const ARCHBAR_HTML='<div class="opg-arb">\n<style>\n.opg-arb{margin:14px 0;font-family:"Courier New","Microsoft YaHei",monospace;display:flex;align-items:center;gap:8px}\n.opg-arb-lb,.opg-arb-vl{font-weight:700;font-size:12px;color:#f0f7f4;letter-spacing:1px}\n.opg-arb-tr{flex:1;max-width:360px;height:10px;border:1.5px solid #a2e3c4;background:rgba(240,247,244,.08);position:relative;overflow:hidden}\n.opg-arb-fl{position:absolute;left:0;top:0;bottom:0;width:68%;background:#a2e3c4;border-right:1.5px solid #f0f7f4}\n@media (max-width:430px){.opg-arb{flex-wrap:wrap}}\n</style>\n<span class="opg-arb-lb">依存度</span><div class="opg-arb-tr"><div class="opg-arb-fl"></div></div><span class="opg-arb-vl">68%</span>\n</div>';
const ARCHINV_HTML='<div class="opg-ari">\n<style>\n.opg-ari{margin:14px 0;font-family:"Courier New","Microsoft YaHei",monospace;display:flex;flex-direction:column;gap:8px}\n.opg-ari-hd{font-size:13px;font-weight:700;color:#f0f7f4;border-bottom:3px solid #a2e3c4;display:inline-block;padding-bottom:2px;letter-spacing:2px}\n.opg-ari-row{display:flex;align-items:center;border:1.5px solid #7e8d85;padding:8px;background:rgba(255,255,255,.05);transition:transform .2s,background .2s}\n.opg-ari-row:hover{transform:translateX(5px);background:rgba(162,227,196,.12)}\n.opg-ari-ic{width:28px;height:28px;background:#a2e3c4;border:1.5px solid #7e8d85;display:flex;align-items:center;justify-content:center;margin-right:10px;font-weight:700;font-size:11px;color:#1c2420;flex-shrink:0}\n.opg-ari-nm{font-weight:700;font-size:12.5px;color:#f0f7f4;display:block}\n.opg-ari-ds{font-size:11px;color:#b3bfb8}\n.opg-ari-ct{margin-left:auto;background:#3c493f;color:#a2e3c4;padding:2px 6px;font-size:11px;border-radius:3px;flex-shrink:0}\n@media (prefers-reduced-motion:reduce){.opg-ari-row{transition:none}}\n</style>\n<div class="opg-ari-hd">物品清单</div>\n<div class="opg-ari-row"><div class="opg-ari-ic">KY</div><div><span class="opg-ari-nm">黄铜钥匙</span><span class="opg-ari-ds">能打开某扇被遗忘的门</span></div><span class="opg-ari-ct">×1</span></div>\n<div class="opg-ari-row"><div class="opg-ari-ic">RX</div><div><span class="opg-ari-nm">薄荷糖</span><span class="opg-ari-ds">她说紧张的时候含一颗</span></div><span class="opg-ari-ct">×3</span></div>\n<div class="opg-ari-row"><div class="opg-ari-ic">ID</div><div><span class="opg-ari-nm">旧工作证</span><span class="opg-ari-ds">照片上的脸已经看不清了</span></div><span class="opg-ari-ct">×1</span></div>\n</div>';
const ARCHTITLE_HTML='<div class="opg-art">\n<style>\n.opg-art{margin:14px 0;font-family:"Courier New","Microsoft YaHei",monospace}\n.opg-art-hd{font-size:13px;font-weight:700;color:#f0f7f4;border-bottom:3px solid #a2e3c4;display:inline-block;padding-bottom:2px;letter-spacing:2px;margin-bottom:8px}\n.opg-art-gd{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:8px}\n.opg-art-box{border:1.5px solid #7e8d85;padding:8px;background:rgba(255,255,255,.05);box-shadow:3px 3px 0 rgba(162,227,196,.18)}\n.opg-art-nm{background:#3c493f;color:#a2e3c4;display:inline-block;padding:2px 6px;font-size:11px;font-weight:700;letter-spacing:1px;margin-bottom:4px}\n.opg-art-ef{font-size:11.5px;color:#f0f7f4;margin-bottom:3px;line-height:1.6}\n.opg-art-qt{font-size:10.5px;color:#b3bfb8;font-style:italic;line-height:1.6}\n@media (max-width:430px){.opg-art-gd{grid-template-columns:1fr}}\n</style>\n<div class="opg-art-hd">当前称号</div>\n<div class="opg-art-gd">\n<div class="opg-art-box"><span class="opg-art-nm">雨夜同行者</span><div class="opg-art-ef">雨天同行时，她的话会变多。</div><div class="opg-art-qt">"才不是因为伞太小。"</div></div>\n<div class="opg-art-box"><span class="opg-art-nm">档案管理员</span><div class="opg-art-ef">可以翻看她允许翻看的旧档案。</div><div class="opg-art-qt">"轻一点，纸会碎。"</div></div>\n</div>\n</div>';

